const COLOR = { collar: '#a7c1f4', placa: '#3160a6', letras: '#f5f5f2', podio: '#e9cff5', metal: '#d5d9e0' };

// Medidas en mm (collar talla M cerrado)
const R = 52, ZF = 41, SUAVE = 4;          // recorrido: círculo con el frente plano donde va la hebilla
const ANCHO = 20, GROSOR = 2.6;             // cinta
const S_ARGOLLA = 58;                       // centro de la argolla sobre la cinta (mm desde el frente)
const CON_PODIO = false;                    // podio lila bajo el collar (como en las fotos)
const Y_PODIO = -84, R_PODIO = 50, H_PODIO = 12;
const Y_PISO = CON_PODIO ? Y_PODIO - H_PODIO : -81;   // piso donde cae la sombra

const POSTER = typeof window !== 'undefined' && window.__collarPoster === true;

function esperarCarga() {
  return new Promise(res => {
    const idle = () => ('requestIdleCallback' in window) ? requestIdleCallback(() => res(), { timeout: 1500 }) : setTimeout(res, 300);
    if (document.readyState === 'complete') idle(); else addEventListener('load', idle, { once: true });
  });
}
function hayWebGL() {
  try { const c = document.createElement('canvas'); return !!(c.getContext('webgl2') || c.getContext('webgl')); } catch (e) { return false; }
}

async function arrancar(stage) {
  if (!hayWebGL()) return;
  if (!POSTER) await esperarCarga();
  let THREE;
  try { THREE = await import(THREE_URL); } catch (e) { return; }   // sin red: se queda la imagen
  try { montar(THREE, stage); } catch (e) { console.warn('Collar 3D:', e); }
}

// ---------------------------------------------------------------- geometría
function crearRecorrido(THREE) {
  const M = 2048, pts = [];
  const smin = (a, b, k) => -k * Math.log(Math.exp(-a / k) + Math.exp(-b / k));
  for (let i = 0; i <= M; i++) { const f = i / M * Math.PI * 2; pts.push([R * Math.sin(f), smin(R * Math.cos(f), ZF, SUAVE)]); }
  const L = [0];
  for (let i = 1; i <= M; i++) L.push(L[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  const total = L[M];
  function en(s) {
    s = ((s % total) + total) % total;
    let lo = 0, hi = M;
    while (hi - lo > 1) { const m = (lo + hi) >> 1; if (L[m] <= s) lo = m; else hi = m; }
    const k = (s - L[lo]) / ((L[hi] - L[lo]) || 1);
    const x = pts[lo][0] + (pts[hi][0] - pts[lo][0]) * k, z = pts[lo][1] + (pts[hi][1] - pts[lo][1]) * k;
    let tx = pts[hi][0] - pts[lo][0], tz = pts[hi][1] - pts[lo][1]; const l = Math.hypot(tx, tz) || 1; tx /= l; tz /= l;
    return { p: new THREE.Vector3(x, 0, z), t: new THREE.Vector3(tx, 0, tz), n: new THREE.Vector3(-tz, 0, tx) };
  }
  return { en, total };
}

// rectángulo redondeado (u = hacia afuera, v = hacia arriba), en sentido antihorario
function perfil(a, b, r, seg = 3) {
  const P = [], E = [[a - r, b - r, 0], [-a + r, b - r, 90], [-a + r, -b + r, 180], [a - r, -b + r, 270]];
  for (const [cx, cy, a0] of E) for (let i = 0; i <= seg; i++) { const g = (a0 + 90 * i / seg) * Math.PI / 180; P.push([cx + r * Math.cos(g), cy + r * Math.sin(g)]); }
  return P;
}

// cinta: barre el perfil a lo largo del recorrido entre s0 y s1
function cinta(THREE, rec, s0, s1, { off = 0, a = GROSOR / 2, b = ANCHO / 2, r = 0.9, paso = 1.1, cerrada = false, punta = false } = {}) {
  const prof = perfil(a, b, r), np = prof.length;
  const n = Math.max(2, Math.ceil((s1 - s0) / paso)), filas = cerrada ? n : n + 1;
  const pos = [], centros = [];
  for (let i = 0; i < filas; i++) {
    const f = rec.en(s0 + (s1 - s0) * i / n);
    const c = f.p.clone().addScaledVector(f.n, off); centros.push(c);
    // punta redondeada: en los primeros mm el ancho se cierra en semicírculo
    const d = (s1 - s0) * i / n, k = punta && d < b ? Math.sqrt(Math.max(0.03, 1 - ((b - d) / b) ** 2)) : 1;
    for (const [u, v] of prof) pos.push(c.x + f.n.x * u, v * k, c.z + f.n.z * u);
  }
  const idx = [], V = i => new THREE.Vector3(pos[3 * i], pos[3 * i + 1], pos[3 * i + 2]);
  const tri = (i, j, k, afuera) => {
    const A = V(i), B = V(j), C = V(k), nn = B.clone().sub(A).cross(C.clone().sub(A));
    if (nn.dot(afuera) >= 0) idx.push(i, j, k); else idx.push(i, k, j);
  };
  for (let i = 0; i < n; i++) {
    const i2 = cerrada ? (i + 1) % filas : i + 1, cm = centros[i].clone().add(centros[i2]).multiplyScalar(0.5);
    for (let j = 0; j < np; j++) {
      const j2 = (j + 1) % np, a0 = i * np + j, a1 = i * np + j2, b0 = i2 * np + j, b1 = i2 * np + j2;
      const mid = V(a0).add(V(a1)).add(V(b0)).add(V(b1)).multiplyScalar(0.25), afuera = mid.sub(cm);
      tri(a0, b0, a1, afuera); tri(a1, b0, b1, afuera);
    }
  }
  if (!cerrada) {
    for (const [fila, signo] of [[0, -1], [filas - 1, 1]]) {
      const c = centros[fila], ci = pos.length / 3; pos.push(c.x, 0, c.z);
      const f = rec.en(fila === 0 ? s0 : s1), dir = f.t.clone().multiplyScalar(signo);
      for (let j = 0; j < np; j++) tri(ci, fila * np + j, fila * np + (j + 1) % np, dir);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setIndex(idx); g.computeVertexNormals();
  return g;
}

function rectRedondeado(THREE, w, h, r, ruta, cx = 0, cy = 0) {
  const s = ruta || new THREE.Shape(), x = cx - w / 2, y = cy - h / 2;
  r = Math.min(r, w / 2, h / 2);
  s.moveTo(x + r, y); s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y);
  return s;
}
// pieza extruida a lo largo de la normal, centrada en w; bisel suave
function pieza(THREE, shape, prof, bisel = 0.7) {
  const g = new THREE.ExtrudeGeometry(shape, { depth: Math.max(0.1, prof - 2 * bisel), bevelEnabled: true, bevelThickness: bisel, bevelSize: bisel * 0.8, bevelSegments: 3, curveSegments: 10 });
  g.translate(0, 0, -prof / 2 + bisel);
  return g;
}
function caja(THREE, w, h, prof, r, bisel) { return pieza(THREE, rectRedondeado(THREE, w - 1.6 * bisel, h - 1.6 * bisel, r), prof, bisel); }

// coloca una geometría local (x = a lo largo de la cinta, y = arriba, z = hacia afuera) en el punto s
function aCinta(THREE, g, rec, s, u = 0, v = 0, w = 0) {
  const f = rec.en(s), Y = new THREE.Vector3(0, 1, 0);
  const m = new THREE.Matrix4().makeBasis(f.t, Y, f.n);
  m.setPosition(f.p.clone().addScaledVector(f.t, u).addScaledVector(Y, v).addScaledVector(f.n, w));
  return g.applyMatrix4(m);
}

function remache(THREE) {
  const p = [[3.85, 0], [3.85, 0.3], [3.65, 0.72], [3.2, 1.05], [2.5, 1.28], [1.4, 1.42], [0, 1.45]].map(([x, y]) => new THREE.Vector2(x, y));
  const g = new THREE.LatheGeometry(p, 40);
  g.rotateX(Math.PI / 2);          // eje del remache = z (hacia afuera)
  return g;
}

function leerFormas(THREE, lista) {
  const pts = t => t.split(' ').map(q => { const [x, y] = q.split(','); return new THREE.Vector2(+x / 20, +y / 20); });
  return lista.map(([ext, ...huecos]) => { const s = new THREE.Shape(pts(ext)); for (const h of huecos) s.holes.push(new THREE.Path(pts(h))); return s; });
}

// ---------------------------------------------------------------- escena
function montar(THREE, stage) {
  const reducido = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: POSTER, powerPreference: 'low-power' });
  renderer.setPixelRatio(POSTER ? 1 : Math.min(window.devicePixelRatio || 1, 2));
  renderer.setClearColor(0x000000, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  const canvas = renderer.domElement;
  canvas.setAttribute('role', 'img');
  canvas.setAttribute('tabindex', '0');
  canvas.setAttribute('aria-label', 'Collar impermeable Wuuff azul cielo con placa NFC en forma de huella. Arrástralo para girarlo.');
  stage.insertBefore(canvas, stage.querySelector('.hero-3d-chip'));

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(24, 6 / 5, 10, 2000);

  // Entorno suave (estudio pastel) para los brillos del recubrimiento y la argollita metálica
  const pmrem = new THREE.PMREMGenerator(renderer);
  const env = new THREE.Scene();
  const domo = new THREE.Mesh(new THREE.SphereGeometry(100, 32, 16), new THREE.MeshBasicMaterial({ side: THREE.BackSide, vertexColors: true }));
  { const c = [], p = domo.geometry.attributes.position; const arriba = new THREE.Color('#ffffff'), abajo = new THREE.Color('#f6cfd4'), medio = new THREE.Color('#c9d0fa');
    for (let i = 0; i < p.count; i++) { const y = p.getY(i) / 100, col = y > 0 ? medio.clone().lerp(arriba, y) : medio.clone().lerp(abajo, -y); c.push(col.r, col.g, col.b); }
    domo.geometry.setAttribute('color', new THREE.Float32BufferAttribute(c, 3)); }
  env.add(domo);
  for (const [x, y, z, s] of [[-60, 70, 60, 50], [70, 40, 50, 35], [0, 90, -40, 40]]) {
    const caja_ = new THREE.Mesh(new THREE.PlaneGeometry(s, s), new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }));
    caja_.position.set(x, y, z); caja_.lookAt(0, 0, 0); env.add(caja_);
  }
  scene.environment = pmrem.fromScene(env, 0.035).texture;

  scene.add(new THREE.HemisphereLight(0xffffff, 0xf3cdd6, 0.55));
  const sol = new THREE.DirectionalLight(0xffffff, 1.7);
  sol.position.set(-55, 230, 75); sol.castShadow = true;
  Object.assign(sol.shadow.camera, { left: -95, right: 95, top: 95, bottom: -95, near: 50, far: 500 });
  sol.shadow.mapSize.set(1024, 1024); sol.shadow.bias = -0.0004; sol.shadow.normalBias = 0.6; sol.shadow.radius = 4;
  scene.add(sol);
  const relleno = new THREE.DirectionalLight(0xeef0ff, 0.45); relleno.position.set(150, 40, 90); scene.add(relleno);
  const contra = new THREE.DirectionalLight(0xffffff, 0.5); contra.position.set(0, 90, -180); scene.add(contra);

  const matCollar = new THREE.MeshPhysicalMaterial({ color: COLOR.collar, roughness: 0.5, clearcoat: 0.35, clearcoatRoughness: 0.45, envMapIntensity: 0.55 });
  const matPlaca = new THREE.MeshStandardMaterial({ color: COLOR.placa, roughness: 0.48, envMapIntensity: 0.5 });
  const matLetras = new THREE.MeshStandardMaterial({ color: COLOR.letras, roughness: 0.55, envMapIntensity: 0.4 });
  const matMetal = new THREE.MeshStandardMaterial({ color: COLOR.metal, metalness: 1, roughness: 0.25, envMapIntensity: 1 });
  const matPodio = new THREE.MeshStandardMaterial({ color: COLOR.podio, roughness: 0.92, envMapIntensity: 0.35 });

  const rec = crearRecorrido(THREE), L = rec.total;
  const collar = new THREE.Group();
  const malla = (g, m) => { const o = new THREE.Mesh(g, m); o.castShadow = true; o.receiveShadow = true; collar.add(o); return o; };

  // cinta principal y la punta sobrante por fuera (sale del pasador y termina en la presilla grande)
  const OFF2 = GROSOR + 0.15;
  malla(cinta(THREE, rec, 0, L, { cerrada: true }), matCollar);
  malla(cinta(THREE, rec, -62, -21, { off: OFF2, r: 1, punta: true }), matCollar);

  // presillas: abrazan la cinta y la punta sobrante
  function presilla(s0, largo, alto) {
    const sh = rectRedondeado(THREE, 9.8, alto, 2.6); sh.holes.push(rectRedondeado(THREE, 6.2, 21, 1.4, new THREE.Path()));
    const g = new THREE.ExtrudeGeometry(sh, { depth: largo - 1.4, bevelEnabled: true, bevelThickness: 0.7, bevelSize: 0.6, bevelSegments: 3, curveSegments: 10 });
    g.translate(OFF2 / 2, 0, -largo / 2 + 0.7);   // x = normal, z = a lo largo de la cinta
    const f = rec.en(s0), m = new THREE.Matrix4().makeBasis(f.n, new THREE.Vector3(0, 1, 0), f.t.clone().negate());
    m.setPosition(f.p); g.applyMatrix4(m); malla(g, matCollar);
  }
  presilla(-56, 6.8, 25.4);
  presilla(-30, 5.6, 24.6);

  // broche de clip (como el del collar Wuuff):
  // macho = pasador con rodillo + base de las patas; hembra = cuerpo con ventanas laterales y ranura para la cinta
  { const fr = rectRedondeado(THREE, 14, 25.5, 3); fr.holes.push(rectRedondeado(THREE, 8.4, 15.5, 2, new THREE.Path()));
    malla(aCinta(THREE, pieza(THREE, fr, 7.8, 0.9), rec, -17.5, 0, 0, 1.0), matCollar);
    const rodillo = new THREE.CylinderGeometry(3.3, 3.3, 15.2, 32); rodillo.scale(1, 1, 0.8);
    malla(aCinta(THREE, rodillo, rec, -17.5, 0, 0, 2.3), matCollar); }
  malla(aCinta(THREE, caja(THREE, 4.6, 23, 7, 1.6, 0.8), rec, -8.4), matCollar);
  { const sh = new THREE.Shape(), r = 3, X = 12, H = 13, n0 = -10, n1 = -4.6, nh = 10.6;
    sh.moveTo(-X + r, -H); sh.lineTo(n0, -H); sh.lineTo(n0, -nh); sh.lineTo(n1, -nh); sh.lineTo(n1, -H);
    sh.lineTo(X - r, -H); sh.quadraticCurveTo(X, -H, X, -H + r); sh.lineTo(X, H - r); sh.quadraticCurveTo(X, H, X - r, H);
    sh.lineTo(n1, H); sh.lineTo(n1, nh); sh.lineTo(n0, nh); sh.lineTo(n0, H);
    sh.lineTo(-X + r, H); sh.quadraticCurveTo(-X, H, -X, H - r); sh.lineTo(-X, -H + r); sh.quadraticCurveTo(-X, -H, -X + r, -H);
    sh.holes.push(rectRedondeado(THREE, 3.2, 19.4, 1.2, new THREE.Path(), 8.2, 0));   // ranura por donde pasa la cinta
    malla(aCinta(THREE, pieza(THREE, sh, 8.6, 1.0), rec, 6), matCollar);
    // puntas de las patas del macho asomadas en las ventanas laterales
    for (const v of [-11.7, 11.7]) malla(aCinta(THREE, caja(THREE, 4.6, 2.2, 5.2, 0.7, 0.5), rec, 6 + (n0 + n1) / 2, 0, v, 0.2), matCollar);
    // panel central en relieve
    malla(aCinta(THREE, caja(THREE, 11, 12.5, 1.4, 2.2, 0.45), rec, 3, 0, 0, 4.2), matCollar); }

  // lengüeta que sale de la hembra, con dos remaches, y la argolla doblada al final
  malla(cinta(THREE, rec, 13, 46, { off: OFF2, r: 1 }), matCollar);
  malla(aCinta(THREE, remache(THREE), rec, 25, 0, 0, GROSOR / 2 + OFF2), matCollar);
  malla(aCinta(THREE, remache(THREE), rec, 36, 0, 0, GROSOR / 2 + OFF2), matCollar);
  const W_ARG = 3.5, R_ARG = 12, T_ARG = 1.9;
  malla(aCinta(THREE, new THREE.CylinderGeometry(2.35, 2.35, ANCHO, 28), rec, S_ARGOLLA - R_ARG, 0, 0, 3.15), matCollar);
  malla(aCinta(THREE, new THREE.TorusGeometry(R_ARG, T_ARG, 22, 80), rec, S_ARGOLLA, 0, 0, W_ARG), matCollar);

  // colgante: argollita metálica + placa huella. Pivote en la parte baja de la argolla.
  const fA = rec.en(S_ARGOLLA), Y = new THREE.Vector3(0, 1, 0);
  const soporte = new THREE.Group();
  soporte.matrixAutoUpdate = false;
  soporte.matrix.makeBasis(fA.t, Y, fA.n).setPosition(fA.p.clone().addScaledVector(Y, -R_ARG).addScaledVector(fA.n, W_ARG));
  collar.add(soporte);
  const pendulo = new THREE.Group(); pendulo.rotation.order = 'XZY'; soporte.add(pendulo);
  const R_SPLIT = 5.6, T_SPLIT = 0.75, ySplit = T_ARG + T_SPLIT - R_SPLIT;
  { const g = new THREE.TorusGeometry(R_SPLIT, T_SPLIT, 14, 56); g.rotateY(Math.PI / 2);
    const o = new THREE.Mesh(g, matMetal); o.position.y = ySplit; o.castShadow = true; pendulo.add(o); }
  const placa = new THREE.Group();
  const ag = DATOS.agujero;
  placa.position.set(-ag.x, ySplit - R_SPLIT - (ag.d / 2 - T_SPLIT) - ag.y, 0);
  pendulo.add(placa);
  const extruir = (formas, prof, z, mat, bisel) => {
    const g = new THREE.ExtrudeGeometry(formas, { depth: prof - (bisel ? 2 * bisel : 0), bevelEnabled: !!bisel, bevelThickness: bisel || 0, bevelSize: (bisel || 0) * 0.7, bevelSegments: 2, curveSegments: 1 });
    g.translate(0, 0, z + (bisel || 0));
    const o = new THREE.Mesh(g, mat); o.castShadow = true; o.receiveShadow = true; return o;
  };
  const G_BASE = DATOS.grosor, G_LET = DATOS.alto;
  placa.add(extruir(leerFormas(THREE, DATOS.base), G_BASE, -G_BASE / 2, matPlaca, 0.45));
  placa.add(extruir(leerFormas(THREE, DATOS.sello), G_LET, G_BASE / 2 - 0.05, matLetras, 0.18));
  const nombres = Object.keys(DATOS.nombres), cache = {};
  let iNombre = 0, letras = null;
  function ponerNombre(i) {
    iNombre = (i + nombres.length) % nombres.length;
    const n = nombres[iNombre];
    if (letras) placa.remove(letras);
    letras = cache[n] || (cache[n] = extruir(leerFormas(THREE, DATOS.nombres[n]), G_LET, G_BASE / 2 - 0.05, matLetras, 0.18));
    placa.add(letras);
    stage.dataset.nombre = n;
  }
  ponerNombre(0);

  scene.add(collar);

  // podio lila (opcional), sombra real del collar sobre el piso y sombra de contacto suave
  if (CON_PODIO) { const p = [[0, 0], [R_PODIO - 3.8, 0], [R_PODIO - 1.2, -0.5], [R_PODIO, -2.4], [R_PODIO, -H_PODIO]].map(([x, y]) => new THREE.Vector2(x, y));
    const g = new THREE.LatheGeometry(p.reverse(), 120); g.translate(0, Y_PODIO, 0);
    const o = new THREE.Mesh(g, matPodio); o.receiveShadow = true; scene.add(o); }
  { const c = document.createElement('canvas'); c.width = c.height = 128; const x = c.getContext('2d');
    const gr = x.createRadialGradient(64, 64, 18, 64, 64, 64); gr.addColorStop(0, 'rgba(120,72,120,0.30)'); gr.addColorStop(1, 'rgba(120,72,120,0)');
    x.fillStyle = gr; x.fillRect(0, 0, 128, 128);
    const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
    const o = new THREE.Mesh(new THREE.PlaneGeometry(150, 150), new THREE.MeshBasicMaterial({ map: t, transparent: true, depthWrite: false, opacity: CON_PODIO ? 1 : 0.55 }));
    o.rotation.x = -Math.PI / 2; o.position.y = Y_PISO - 0.2; o.renderOrder = -1; scene.add(o); }
  if (!CON_PODIO) {
    const o = new THREE.Mesh(new THREE.PlaneGeometry(400, 400), new THREE.ShadowMaterial({ color: 0x6a4f9a, opacity: 0.12, depthWrite: false }));
    o.rotation.x = -Math.PI / 2; o.position.y = Y_PISO; o.receiveShadow = true; scene.add(o);
  }

  // ------------------------------------------------ cámara y encuadre
  const ELEV = (CON_PODIO ? 22 : 19) * Math.PI / 180;
  const MIRA = new THREE.Vector3(0, -40, 0);
  let dist = 320;
  // puntos que deben caber en cualquier giro: collar (con placa) y podio
  const CABER = [];
  for (let a = 0; a < 360; a += 15) {
    const c = Math.cos(a * Math.PI / 180), s_ = Math.sin(a * Math.PI / 180);
    CABER.push([60 * c, 15, 60 * s_], [60 * c, -72, 60 * s_]);
    if (CON_PODIO) CABER.push([R_PODIO * c, Y_PODIO, R_PODIO * s_], [R_PODIO * c, Y_PODIO - H_PODIO, R_PODIO * s_]);
    else CABER.push([22 * c, Y_PISO, 22 * s_]);
  }
  function encuadrar() {
    const w = stage.clientWidth || 400, h = stage.clientHeight || 300;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    ponerCamara();
  }
  function colocar() {
    camera.position.set(0, MIRA.y + Math.sin(ELEV) * dist, Math.cos(ELEV) * dist);
    camera.lookAt(MIRA); camera.updateProjectionMatrix(); camera.updateMatrixWorld();
  }
  function ponerCamara() {
    // ajusta distancia y altura de la mira para que todo quepa: abajo deja espacio para la etiqueta
    const v = new THREE.Vector3();
    for (let i = 0; i < 40; i++) {
      colocar();
      let x0 = 1, x1 = -1, y0 = 1, y1 = -1;
      for (const q of CABER) { v.set(q[0], q[1], q[2]).project(camera); x0 = Math.min(x0, v.x); x1 = Math.max(x1, v.x); y0 = Math.min(y0, v.y); y1 = Math.max(y1, v.y); }
      const LIM_X = 0.97, ARR = 0.8, ABA = -0.95;
      const esc = Math.max((x1 - x0) / (2 * LIM_X), (y1 - y0) / (ARR - ABA));
      dist *= Math.pow(esc, 0.7);
      const centro = (y1 + y0) / 2, deseado = (ARR + ABA) / 2;
      MIRA.y += (centro - deseado) * dist * Math.tan(camera.fov * Math.PI / 360) * 0.7;
    }
    colocar();
    // altura del horizonte del piso (fondo del podio) para el CSS
    const q = CON_PODIO ? new THREE.Vector3(0, Y_PODIO - H_PODIO * 0.4, -R_PODIO).project(camera) : new THREE.Vector3(0, Y_PISO, -95).project(camera);
    stage.style.setProperty('--horizonte', ((1 - (q.y + 1) / 2) * 100).toFixed(1) + '%');
  }
  encuadrar();

  // ------------------------------------------------ animación e interacción
  const AUTO = reducido ? 0 : 0.26;           // rad/s (una vuelta cada ~24 s)
  const facing = Math.atan2(fA.n.x, fA.n.z); // ángulo de la placa respecto al frente
  let yaw = -facing + 0.55, vel = AUTO, arrastre = null, tocado = false, ultimoToque = -1e9;
  let psi = 0, dpsi = 0, th = 0, dth = 0, velPrev = vel, armado = false;

  function cara() { let f = yaw + facing; f = Math.atan2(Math.sin(f), Math.cos(f)); return f; }

  canvas.addEventListener('pointerdown', e => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    arrastre = { id: e.pointerId, x: e.clientX, y: e.clientY, t: performance.now(), tipo: e.pointerType };
    try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
    canvas.classList.add('arrastrando');
    if (!tocado) { tocado = true; stage.classList.add('tocado'); }
  });
  canvas.addEventListener('pointermove', e => {
    if (!arrastre || e.pointerId !== arrastre.id) return;
    const now = performance.now(), dt = Math.max(1, now - arrastre.t) / 1000;
    const dx = e.clientX - arrastre.x;
    const k = 6.2 / Math.max(260, stage.clientWidth);           // una pasada completa ≈ una vuelta
    yaw += dx * k; vel = vel * 0.4 + (dx * k / dt) * 0.6;
    arrastre.x = e.clientX; arrastre.y = e.clientY; arrastre.t = now; ultimoToque = now;
  });
  const soltar = e => {
    if (!arrastre || (e && e.pointerId !== arrastre.id)) return;
    if (performance.now() - arrastre.t > 90) vel = 0;           // se quedó quieto antes de soltar
    vel = Math.max(-9, Math.min(9, vel));
    arrastre = null; canvas.classList.remove('arrastrando'); ultimoToque = performance.now();
  };
  canvas.addEventListener('pointerup', soltar);
  canvas.addEventListener('pointercancel', soltar);
  canvas.addEventListener('lostpointercapture', soltar);
  canvas.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
      e.preventDefault(); vel = (e.key === 'ArrowLeft' ? -1 : 1) * 2.4; ultimoToque = performance.now();
      if (!tocado) { tocado = true; stage.classList.add('tocado'); }
    }
  });

  let visible = true, enPantalla = true, raf = 0, tPrev = performance.now(), t0 = tPrev;
  function paso(now) {
    raf = 0;
    // en reposo basta con ~30 cuadros por segundo (ahorra batería en el celular)
    const quieto = !arrastre && Math.abs(vel - AUTO) < 0.05 && Math.abs(dpsi) < 0.02 && Math.abs(dth) < 0.02;
    if (quieto && now - tPrev < 30) { if (visible && enPantalla) raf = requestAnimationFrame(paso); return; }
    const dt = Math.min(0.05, (now - tPrev) / 1000); tPrev = now;
    if (!arrastre) {
      const k = now - ultimoToque < 1500 ? 0.9 : 2.2;            // inercia y luego vuelve al giro lento
      vel += (AUTO - vel) * (1 - Math.exp(-dt * k));
      yaw += vel * dt;
    }
    const acel = Math.max(-40, Math.min(40, (vel - velPrev) / Math.max(dt, 1e-3))); velPrev = vel;
    // la placa se mece: hacia afuera por la velocidad de giro y de lado por los cambios de velocidad
    const thObj = Math.min(0.55, vel * vel * 0.012);
    dth += (-(th - thObj) * 70 - dth * 5) * dt; th += dth * dt;
    dpsi += (-psi * 55 - dpsi * 3.2 - acel * 0.11) * dt; psi += dpsi * dt;
    psi = Math.max(-0.7, Math.min(0.7, psi));
    pendulo.rotation.x = th; pendulo.rotation.z = psi;
    collar.rotation.y = yaw;
    collar.position.y = reducido ? 0 : Math.sin((now - t0) / 1000 * 1.25) * 2.2;
    // cambia el nombre cuando la placa queda de espaldas
    const f = Math.abs(cara());
    if (f < 1.1) armado = true;
    if (armado && f > 2.4) { armado = false; ponerNombre(iNombre + (vel >= 0 ? 1 : -1)); }
    renderer.render(scene, camera);
    if (visible && enPantalla) raf = requestAnimationFrame(paso);
  }
  function reanudar() { if (!raf && visible && enPantalla) { tPrev = performance.now(); raf = requestAnimationFrame(paso); } }

  if (POSTER) {
    if (typeof window.__collarGiro === 'number') yaw = -facing + window.__collarGiro;
    collar.position.y = 0; collar.rotation.y = yaw; renderer.render(scene, camera);
    window.__collarListo = true;
    return;
  }
  document.addEventListener('visibilitychange', () => { visible = !document.hidden; reanudar(); });
  if ('IntersectionObserver' in window) new IntersectionObserver(es => { enPantalla = es[0].isIntersecting; reanudar(); }, { rootMargin: '80px' }).observe(stage);
  if ('ResizeObserver' in window) new ResizeObserver(() => { encuadrar(); if (!raf) renderer.render(scene, camera); }).observe(stage);
  else addEventListener('resize', encuadrar);

  const pista = document.createElement('span'); pista.className = 'hero-3d-pista'; pista.setAttribute('aria-hidden', 'true');
  pista.textContent = '↔ Desliza para girarlo';
  stage.appendChild(pista);
  renderer.render(scene, camera);
  requestAnimationFrame(() => { stage.classList.add('listo'); reanudar(); });
  setTimeout(() => stage.classList.add('tocado'), 9000);
}

const el = typeof document !== 'undefined' && document.querySelector('[data-collar-3d]');
if (el) arrancar(el);
